#define MOD 1000003LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    a %= MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    static long long fact[1000003];
    int Q;

    fact[0] = 1;
    for (int i = 1; i < MOD; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
    }

    if (scanf("%d", &Q) != 1) return 0;

    while (Q--) {
        long long x, d, n;
        scanf("%lld %lld %lld", &x, &d, &n);

        x %= MOD;
        d %= MOD;
        if (x < 0) x += MOD;
        if (d < 0) d += MOD;

        if (n == 0) {
            printf("1\n");
            continue;
        }

        if (d == 0) {
            printf("%lld\n", mod_pow(x, n));
            continue;
        }

        long long inv_d = mod_pow(d, MOD - 2);
        long long a = (x * inv_d) % MOD;   // sequence becomes d^n * (a)(a+1)...(a+n-1)

        if (a == 0) {
            printf("0\n");
            continue;
        }

        /* If among a, a+1, ..., a+n-1 there is a multiple of MOD, product is 0.
           Since MOD is prime and values are considered modulo MOD, this happens iff
           a + n - 1 >= MOD. */
        if (a + n - 1 >= MOD) {
            printf("0\n");
            continue;
        }

        long long num = fact[a + n - 1];
        long long den_inv = mod_pow(fact[a - 1], MOD - 2);
        long long ans = mod_pow(d, n);
        ans = (ans * num) % MOD;
        ans = (ans * den_inv) % MOD;

        printf("%lld\n", ans);
    }

    return 0;
}

