int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Precompute factorials modulo MOD
    vector<long long> fact(MOD), invfact(MOD);
    fact[0] = 1;
    for (int i = 1; i < MOD; ++i) fact[i] = fact[i - 1] * i % MOD;

    invfact[MOD - 1] = mod_pow(fact[MOD - 1], MOD - 2);
    for (int i = MOD - 2; i >= 0; --i) {
        invfact[i] = invfact[i + 1] * (i + 1) % MOD;
    }

    int Q;
    cin >> Q;
    while (Q--) {
        long long x, d, n;
        cin >> x >> d >> n;

        x %= MOD;
        d %= MOD;
        if (x < 0) x += MOD;
        if (d < 0) d += MOD;

        if (n == 0) {
            cout << 1 << '\n';
            continue;
        }

        if (d == 0) {
            cout << mod_pow(x, n) << '\n';
            continue;
        }

        long long inv_d = mod_pow(d, MOD - 2);
        long long a = x * inv_d % MOD; // sequence becomes d^n * a(a+1)...(a+n-1)

        // If any term is 0 mod MOD, product is 0
        // This happens iff among a, a+1, ..., a+n-1 there is a multiple of MOD.
        if (a == 0 || a + n - 1 >= MOD) {
            cout << 0 << '\n';
            continue;
        }

        long long prod = fact[a + n - 1] * invfact[a - 1] % MOD;
        prod = prod * mod_pow(d, n) % MOD;
        cout << prod << '\n';
    }

    return 0;
}

