    static long[] fact = new long[MOD];
    static long[] inv_fact = new long[MOD];

    public static void main(String[] args) throws IOException {
        fact[0] = 1;
        for (int i = 1; i < MOD; i++) fact[i] = fact[i-1] * i % MOD;
        inv_fact[MOD-1] = modpow(fact[MOD-1], MOD-2, MOD);
        for (int i = MOD-2; i >= 0; i--) inv_fact[i] = inv_fact[i+1] * (i+1) % MOD;

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int Q = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();
        while (Q-- > 0) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            long x = Long.parseLong(st.nextToken()) % MOD;
            if (x < 0) x += MOD;
            long d = Long.parseLong(st.nextToken()) % MOD;
            if (d < 0) d += MOD;
            long n = Long.parseLong(st.nextToken());

            if (n == 0) { sb.append(1).append('\n'); continue; }
            if (d == 0) { sb.append(modpow(x, n, MOD)).append('\n'); continue; }
            if (n >= MOD) { sb.append(0).append('\n'); continue; }

            int ni = (int) n;
            long a = x * modpow(d, MOD-2, MOD) % MOD;
            // product = d^n * a*(a+1)*...*(a+n-1) mod MOD
            // check if any term in [a, a+n-1] mod MOD is 0
            // a is in [0, MOD-1], n < MOD
            // terms wrap around if a+n-1 >= MOD
            long dn = modpow(d, ni, MOD);
            long prod;
            if (a == 0) { prod = 0; }
            else if (a + ni - 1 < MOD) {
                prod = fact[(int)(a+ni-1)] * inv_fact[(int)(a-1)] % MOD;
            } else {
                // wraps: includes 0 mod MOD
                prod = 0;
            }
            sb.append(dn * prod % MOD).append('\n');
        }
        System.out.print(sb);
    }

    static long modpow(long base, long exp, long mod) {
        long result = 1; base %= mod;
        if (base < 0) base += mod;
        while (exp > 0) { if ((exp&1)==1) result=result*base%mod; base=base*base%mod; exp>>=1; }
        return result;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int MOD = 1_000_003;

    static long[] fact = new long[MOD];
    static long[] invFact = new long[MOD];

    static long modPow(long a, long e) {
        long r = 1;
        a %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = (r * a) % MOD;
            a = (a * a) % MOD;
            e >>= 1;
        }
        return r;
    }

    static void precompute() {
        fact[0] = 1;
        for (int i = 1; i < MOD; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
        }
        invFact[MOD - 1] = modPow(fact[MOD - 1], MOD - 2);
        for (int i = MOD - 2; i >= 0; i--) {
            invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
        }
    }

    static long solveQuery(long x, long d, long n) {
        x %= MOD;
        if (x < 0) x += MOD;
        d %= MOD;
        if (d < 0) d += MOD;

        if (n == 0) return 1;

        if (d == 0) {
            return modPow(x, n);
        }

        if (n >= MOD) return 0;

        long invD = modPow(d, MOD - 2);
        long a = (x * invD) % MOD; // first term divided by d modulo MOD

        // Product = d^n * a(a+1)...(a+n-1)
        // If any factor becomes 0 modulo MOD, answer is 0.
        if (a == 0) return 0;
        if (a + n - 1 >= MOD) return 0;

        long rising = fact[(int)(a + n - 1)] * invFact[(int)(a - 1)] % MOD;
        return modPow(d, n) * rising % MOD;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        precompute();

        int Q = fs.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < Q; i++) {
            long x = fs.nextLong();
            long d = fs.nextLong();
            long n = fs.nextLong();
            sb.append(solveQuery(x, d, n)).append('\n');
        }
        System.out.print(sb.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
